"]}}}, "swords_07": {"zh": {"key": "swords_07", "name": "宝剑七", "upright": {"core": "偷偷摸摸绕开正面，有人没说实话", "keywords": ["隐瞒", "策略", "独行", "取巧"]}, "reversed": {"core": "被揭穿，或良心不安想坦白", "keywords": ["坦白", "被发现", "良心", "不再取巧"]}}, "en": {"key": "swords_07", "name": "Seven of Swords", "upright": {"core": "Sneaking around, avoiding the front door; someone's not being straight", "keywords": ["deception", "strategy", "going it alone", "cunning"]}, "reversed": {"core": "Caught out, or conscience pushing toward the truth", "keywords": ["confession", "exposure", "conscience", "coming clean"]}}}, "swords_08": {"zh": {"key": "swords_08", "name": "宝剑八", "upright": {"core": "被自己的想法困住，其实绳子是松的", "keywords": ["受困", "限制", "自我设限", "无力感"]}, "reversed": {"core": "意识到能走出来，开始解开束缚", "keywords": ["解脱", "新视角", "自由", "重拾力量"]}}, "en": {"key": "swords_08", "name": "Eight of Swords", "upright": {"core": "Trapped by your own thoughts — the bindings are looser than they feel", "keywords": ["restriction", "self-limiting", "helplessness", "stuck"]}, "reversed": {"core": "Realising you can walk out; loosening the ties", "keywords": ["release", "new perspective", "freedom", "regaining power"]}}}, "swords_09": {"zh": {"key": "swords_09", "name": "宝剑九", "upright": {"core": "半夜醒来想太多，焦虑比事情本身还大", "keywords": ["焦虑", "失眠", "担忧", "自责"]}, "reversed": {"core": "最坏的担心在退，或者焦虑到了顶点", "keywords": ["走出焦虑", "求助", "释怀", "绝望顶点"]}}, "en": {"key": "swords_09", "name": "Nine of Swords", "upright": {"core": "Awake at night, the worry bigger than the thing itself", "keywords": ["anxiety", "insomnia", "worry", "guilt"]}, "reversed": {"core": "The worst fears easing, or anxiety at its peak", "keywords": ["relief", "reaching out", "letting go", "despair peaking"]}}}, "swords_10": {"zh": {"key": "swords_10", "name": "宝剑十", "upright": {"core": "到底了，最坏的已经发生，接下来只会往上", "keywords": ["结束", "谷底", "痛苦", "了结"]}, "reversed": {"core": "从谷底慢慢起来，或不肯承认已经结束", "keywords": ["复原", "劫后余生", "拖着不结束", "重生"]}}, "en": {"key": "swords_10", "name": "Ten of Swor